import { smoothstep, type OrbFrame } from './jarvis-orb-motion';

/*
 * The cognitive lattice: the fixed topology of the Jarvis orb, and a pure function that poses it for one frame.
 * This is a line-for-line port of JarvisLatticeModel and JarvisLatticeScene in JarvisCore. The arithmetic, the
 * order of random numbers and every tie-break must stay identical; jarvis-lattice.golden.json (generated by
 * Swift) is the contract that both platforms test against.
 */

export type LatticeLayer = 0 | 1 | 2;
export const shellLayer = 0;
export const midLayer = 1;
export const coreLayer = 2;

export type LatticeNode = {
  x: number;
  y: number;
  z: number;
  layer: LatticeLayer;
  /** Distance from the centre at rest. */
  radius: number;
  /** Index of the small group that drifts in depth together. */
  cluster: number;
  /** 0 cool cyan at the glass, 1 amber at the heart. */
  warmth: number;
  /** Dot radius in orb radii. */
  size: number;
  /** 0 always drawn, 1 from reduced detail, 2 only at full detail. */
  rank: number;
  /** 0–1, spreads twinkle so nodes do not blink together. */
  phase: number;
};

export type LatticeEdge = {
  a: number;
  b: number;
  /** How far the connection curves toward the centre, as a fraction of its midpoint's distance from it. */
  bow: number;
  rank: number;
};

export type LatticeCluster = {
  amplitude: [number, number, number];
  speed: [number, number, number];
  phase: [number, number, number];
};

export type LatticeIgnition = {
  /** Connections from the ignition node to each node; `unreachable` when disconnected. */
  hops: Uint8Array;
  period: number;
  offset: number;
};

export type LatticeRoute = {
  nodes: number[];
  edges: number[];
  /** Whether each hop runs from its edge's `a` to its `b`. */
  forward: boolean[];
  period: number;
  offset: number;
  /** Seconds to cross one connection. */
  hopDuration: number;
};

export type LatticeModel = {
  nodes: LatticeNode[];
  edges: LatticeEdge[];
  clusters: LatticeCluster[];
  ignitions: LatticeIgnition[];
  routes: LatticeRoute[];
  /** Indices of the core nodes, whose centroid is the heart. */
  coreNodes: number[];
};

export const latticeUnreachable = 255;
export const latticeSeed = 1834;
/** The heart's warm pulse repeats every 1.6 seconds. */
export const pulsePeriod = 1.6;

const shellCount = 72;
const midCount = 150;
const coreCount = 120;

type Vector = { x: number; y: number; z: number };

function createRandom(seed: number) {
  let state = seed;
  return () => {
    state = state * 16807 % 2147483647;
    return state / 2147483647;
  };
}

function lengthOf(v: Vector) {
  return Math.sqrt(v.x * v.x + v.y * v.y + v.z * v.z);
}

function distanceBetween(a: Vector, b: Vector) {
  return lengthOf({ x: a.x - b.x, y: a.y - b.y, z: a.z - b.z });
}

function buildLatticeModel(): LatticeModel {
  const random = createRandom(latticeSeed);

  const direction = (): Vector => {
    const y = random() * 2 - 1;
    const angle = random() * Math.PI * 2;
    const ring = Math.sqrt(1 - y * y);
    return { x: Math.cos(angle) * ring, y, z: Math.sin(angle) * ring };
  };

  const positions: { position: Vector; layer: LatticeLayer }[] = [];
  for (let index = 0; index < shellCount; index += 1) {
    const angle = index * 2.39996;
    const y = 1 - 2 * (index + 0.5) / shellCount;
    const ring = Math.sqrt(1 - y * y);
    const jitter = direction();
    const jx = Math.cos(angle) * ring + jitter.x * 0.16;
    const jy = y + jitter.y * 0.16;
    const jz = Math.sin(angle) * ring + jitter.z * 0.16;
    const length = Math.max(Math.sqrt(jx * jx + jy * jy + jz * jz), 1e-6);
    const radius = 0.88 + random() * 0.07;
    positions.push({ position: { x: jx / length * radius, y: jy / length * radius, z: jz / length * radius }, layer: shellLayer });
  }
  for (let index = 0; index < midCount; index += 1) {
    const d = direction();
    const radius = 0.34 + 0.5 * Math.pow(random(), 1.1);
    positions.push({ position: { x: d.x * radius, y: d.y * radius, z: d.z * radius }, layer: midLayer });
  }
  for (let index = 0; index < coreCount; index += 1) {
    const d = direction();
    // A five-lobed star keeps the heart from looking like a ball.
    const lobes = 1 + 0.3 * Math.cos(5 * Math.atan2(d.y, d.x) + 0.6) + 0.1 * Math.cos(3 * Math.atan2(d.y, d.x) - 0.4);
    const radius = 0.56 * Math.pow(random(), 0.78) * lobes;
    positions.push({
      position: { x: d.x * radius * 1.1 + 0.03, y: d.y * radius * 0.94 - 0.02, z: d.z * radius * 0.85 },
      layer: coreLayer,
    });
  }
  const count = positions.length;

  // Clusters: nine drifting centres; every node follows the nearest one.
  const clusterCenters: Vector[] = [];
  const clusters: LatticeCluster[] = [];
  for (let index = 0; index < 9; index += 1) {
    const d = direction();
    const radius = 0.12 + random() * 0.58;
    clusterCenters.push({ x: d.x * radius, y: d.y * radius, z: d.z * radius });
    const amplitude: LatticeCluster['amplitude'] = [0.022 + random() * 0.014, 0.022 + random() * 0.014, 0.085 + random() * 0.05];
    const speed: LatticeCluster['speed'] = [0.2 + random() * 0.24, 0.2 + random() * 0.24, 0.17 + random() * 0.2];
    const phase: LatticeCluster['phase'] = [random() * 6.283, random() * 6.283, random() * 6.283];
    clusters.push({ amplitude, speed, phase });
  }

  // Neighbours by distance; the index breaks ties, so the order never depends on rounding.
  const neighbours: number[][] = [];
  for (let index = 0; index < count; index += 1) {
    const origin = positions[index]!.position;
    const others: number[] = [];
    for (let other = 0; other < count; other += 1) if (other !== index) others.push(other);
    const distances = new Float64Array(count);
    for (const other of others) distances[other] = distanceBetween(origin, positions[other]!.position);
    others.sort((left, right) => {
      const a = distances[left]!;
      const b = distances[right]!;
      return a === b ? left - right : a < b ? -1 : 1;
    });
    neighbours.push(others);
  }

  // Ranks: hubs always show, so the orb still reads as a network at 18 pt.
  const coreByRadius: number[] = [];
  for (let index = 0; index < count; index += 1) if (positions[index]!.layer === coreLayer) coreByRadius.push(index);
  coreByRadius.sort((left, right) => lengthOf(positions[left]!.position) - lengthOf(positions[right]!.position));
  const hubs = new Set(coreByRadius.slice(0, 20));
  for (let index = 0; index < count; index += 1) if (positions[index]!.layer === shellLayer && index % 3 === 0) hubs.add(index);
  for (let index = 0; index < count; index += 1) if (positions[index]!.layer === midLayer && index % 5 === 0) hubs.add(index);

  const nodes: LatticeNode[] = [];
  for (let index = 0; index < count; index += 1) {
    const { position, layer } = positions[index]!;
    const radius = lengthOf(position);
    let nearest = 0;
    let best = Infinity;
    clusterCenters.forEach((center, cluster) => {
      const distance = distanceBetween(position, center);
      if (distance < best) {
        best = distance;
        nearest = cluster;
      }
    });
    const rank = hubs.has(index) ? 0 : index % 2 === 0 ? 1 : 2;
    const warmth = smoothstep(0.92, 0.2, radius);
    const base = layer === shellLayer ? 0.0058 : layer === midLayer ? 0.0042 : 0.0038;
    const size = (base + random() * 0.0034) * (hubs.has(index) ? 1.7 : 1);
    nodes.push({
      x: position.x, y: position.y, z: position.z, layer, radius, cluster: nearest,
      warmth, size, rank, phase: random(),
    });
  }

  // Connections: nearest neighbours, a longer skip for the interior, and one spoke from every shell node to the
  // nearest interior node, so the glass is tied into the core.
  const seen = new Set<number>();
  const edges: LatticeEdge[] = [];
  const connect = (a: number, b: number) => {
    const low = Math.min(a, b);
    const high = Math.max(a, b);
    if (low === high || seen.has(low * 1000 + high)) return;
    seen.add(low * 1000 + high);
    const na = nodes[a]!;
    const nb = nodes[b]!;
    const mid = lengthOf({ x: (na.x + nb.x) / 2, y: (na.y + nb.y) / 2, z: (na.z + nb.z) / 2 });
    const bow = 0.015 + 0.05 * (1 - Math.min(1, mid)) + random() * 0.025;
    edges.push({ a: low, b: high, bow, rank: Math.min(2, na.rank + nb.rank) });
  };
  for (let index = 0; index < count; index += 1) {
    const node = nodes[index]!;
    const reach = node.layer === coreLayer ? 6 : 4;
    for (const neighbour of neighbours[index]!.slice(0, reach)) connect(index, neighbour);
    // Long chords across the interior give the web its star-shaped arcs.
    if (node.layer !== shellLayer) {
      const far: number[] = [];
      for (let other = 0; other < count; other += 1) {
        const candidate = nodes[other]!;
        if (candidate.layer === shellLayer) continue;
        const distance = distanceBetween(node, candidate);
        if (distance >= 0.3 && distance <= 0.62) far.push(other);
      }
      if (far.length > 0 && index % 4 !== 0) {
        connect(index, far[Math.trunc(random() * far.length) % far.length]!);
      }
    }
    if (node.layer === shellLayer) {
      const inward = neighbours[index]!.find((other) => nodes[other]!.layer !== shellLayer);
      if (inward !== undefined) connect(index, inward);
    }
  }

  const adjacency: { node: number; edge: number }[][] = Array.from({ length: count }, () => []);
  edges.forEach((edge, index) => {
    adjacency[edge.a]!.push({ node: edge.b, edge: index });
    adjacency[edge.b]!.push({ node: edge.a, edge: index });
  });

  // Node sequences: eight ignition points among the hubs, with the hop distance to every node.
  const hubList = [...hubs].sort((left, right) => left - right);
  const ignitions: LatticeIgnition[] = [];
  for (let index = 0; index < 8; index += 1) {
    const start = hubList[(Math.trunc(index * hubList.length / 8) + Math.trunc(random() * 3)) % hubList.length]!;
    const hops = new Uint8Array(count).fill(latticeUnreachable);
    hops[start] = 0;
    let frontier = [start];
    while (frontier.length > 0) {
      const next: number[] = [];
      for (const node of frontier) {
        for (const step of adjacency[node]!) {
          if (hops[step.node] !== latticeUnreachable) continue;
          hops[step.node] = hops[node]! + 1;
          next.push(step.node);
        }
      }
      frontier = next;
    }
    const period = 5.2 + random() * 3.4;
    const offset = random() * 8;
    ignitions.push({ hops, period, offset });
  }

  // Signals: from a shell node inward along existing connections, a few hops each.
  const routes: LatticeRoute[] = [];
  const shellNodes: number[] = [];
  for (let index = 0; index < count; index += 1) if (nodes[index]!.layer === shellLayer) shellNodes.push(index);
  let attempt = 0;
  while (routes.length < 22 && attempt < shellNodes.length * 2) {
    const start = shellNodes[(attempt * 7 + 3) % shellNodes.length]!;
    attempt += 1;
    const path = [start];
    const pathEdges: number[] = [];
    const forward: boolean[] = [];
    let current = start;
    while (path.length < 8) {
      const here = nodes[current]!;
      const wanted = here.radius - 0.15;
      const inward = adjacency[current]!
        .filter((step) => nodes[step.node]!.radius < here.radius - 0.02 && !path.includes(step.node))
        .sort((left, right) => {
          const a = Math.abs(nodes[left.node]!.radius - wanted);
          const b = Math.abs(nodes[right.node]!.radius - wanted);
          return a === b ? left.node - right.node : a < b ? -1 : 1;
        });
      const step = inward[0];
      if (!step) break;
      pathEdges.push(step.edge);
      forward.push(edges[step.edge]!.a === current);
      path.push(step.node);
      current = step.node;
      if (nodes[current]!.layer === coreLayer && nodes[current]!.radius < 0.16) break;
    }
    if (path.length < 3) continue;
    const period = 4.4 + random() * 3.6;
    const offset = random() * 9;
    const hopDuration = 0.5 + random() * 0.2;
    routes.push({ nodes: path, edges: pathEdges, forward, period, offset, hopDuration });
  }

  const coreNodes: number[] = [];
  for (let index = 0; index < count; index += 1) if (nodes[index]!.layer === coreLayer) coreNodes.push(index);
  return { nodes, edges, clusters, ignitions, routes, coreNodes };
}

let sharedModel: LatticeModel | null = null;

/** The one lattice every orb shares; built on first use. */
export function getLatticeModel(): LatticeModel {
  sharedModel ??= buildLatticeModel();
  return sharedModel;
}

/**
 * How much of the lattice is drawn. Small orbs keep the hubs and the strongest connections and draw them a little
 * heavier; the large orb shows every node and fine connection.
 */
export type LatticeDetail = 0 | 1 | 2;
export const detailMinimal = 0;
export const detailReduced = 1;
export const detailFull = 2;

export function latticeDetailForSize(points: number): LatticeDetail {
  return points >= 120 ? detailFull : points >= 56 ? detailReduced : detailMinimal;
}

export function latticeLineScale(detail: LatticeDetail) {
  return detail === detailFull ? 1 : detail === detailReduced ? 1.25 : 1.7;
}

function dotScale(detail: LatticeDetail) {
  return detail === detailFull ? 1 : detail === detailReduced ? 1.3 : 1.9;
}

function alphaScale(detail: LatticeDetail) {
  return detail === detailFull ? 1 : detail === detailReduced ? 1.2 : 1.45;
}

export type SceneEdge = {
  ax: number; ay: number; cx: number; cy: number; bx: number; by: number;
  /** 0 cyan, 1 amber. */
  warmth: number;
  /** Brightness of the line itself, before additive blending. */
  alpha: number;
  /** Extra emphasis while neighbouring nodes light up in sequence. */
  light: number;
};

export type SceneDot = {
  x: number;
  y: number;
  radius: number;
  warmth: number;
  alpha: number;
  /** Soft glow around the dot, 0 for none. */
  halo: number;
};

export type SceneHeart = {
  x: number;
  y: number;
  /** Radius of the broad amber glow. */
  radius: number;
  intensity: number;
  /** 0–1 white-hot centre. */
  heat: number;
};

/** One posed frame: plain numbers in orb radii (glass radius 1, y up), ready for any 2D painter. */
export type LatticeScene = {
  detail: LatticeDetail;
  edges: SceneEdge[];
  dots: SceneDot[];
  /** Signal heads and their fading trails. */
  signals: SceneDot[];
  heart: SceneHeart;
  /** 0–1.4 brightness of the cyan limb nodes; the painter lifts the glass rim with it. */
  outerGain: number;
};

function envelope(x: number, decay: number, attack: number) {
  return x <= 0 ? 0 : (1 - Math.exp(-x * attack)) * Math.exp(-x * decay);
}

function wrap(value: number, period: number) {
  const remainder = value % period;
  return remainder < 0 ? remainder + period : remainder;
}

// Swift's rounded(): halves go away from zero.
function roundAwayFromZero(value: number) {
  return value < 0 ? -Math.round(-value) : Math.round(value);
}

/** The heart's warm pulse: a soft double beat once every `pulsePeriod` seconds, 0–1. */
export function latticePulse(time: number) {
  const phase = time / pulsePeriod;
  // Distance around the cycle, so a beat near the start of one cycle never ends abruptly at the previous one.
  const beat = (centre: number, width: number) => {
    let d = phase - centre;
    d -= roundAwayFromZero(d);
    return Math.exp(-Math.pow(d / width, 2));
  };
  return Math.min(1, beat(0.16, 0.1) + 0.45 * beat(0.4, 0.11));
}

export function makeLatticeScene(
  model: LatticeModel,
  frame: OrbFrame,
  detail: LatticeDetail = detailFull,
): LatticeScene {
  const m = frame.motion;
  const t = frame.time;
  const flow = frame.flow;
  const maximumRank = detail;
  const dotsScale = dotScale(detail);
  const alphasScale = alphaScale(detail);

  // State weights ease in, so a change of state starts gently instead of snapping the network.
  const ease = (w: number) => w * w * (3 - 2 * w);
  const listen = ease(m.listen);
  const think = ease(m.think);
  const tool = ease(m.tool);
  const speak = ease(m.speak);

  const awake = m.awake;
  const heldInput = listen * m.input;
  const heldSpeech = speak * m.speech;
  const busy = Math.max(think, tool);
  const pulse = latticePulse(t);

  // Gains: the shell answers to listening, the heart to thinking and speaking.
  const outerGain = 0.5 + 0.5 * awake + 0.5 * listen * (0.3 + m.input) + 0.15 * m.surge + 0.1 * heldSpeech;
  const coreGain = 0.74 + 0.26 * awake + 0.4 * think + 0.3 * tool + 0.4 * heldSpeech
    + 0.4 * heldInput + 0.3 * m.surge;
  const spread = 1 + 0.09 * listen * (0.5 + m.input) - 0.16 * think - 0.07 * tool
    + 0.04 * speak * (0.5 + m.speech) + 0.06 * m.surge;

  const count = model.nodes.length;
  const screenX = new Float64Array(count);
  const screenY = new Float64Array(count);
  const screenZ = new Float64Array(count);
  const lit = new Float64Array(count);

  // Node sequences: each ignition lights its neighbours one hop at a time.
  const seeds = model.ignitions.map((ignition) => ({ tau: wrap(flow + ignition.offset, ignition.period), hops: ignition.hops }));

  model.nodes.forEach((node, index) => {
    const cluster = model.clusters[node.cluster]!;
    const pin = 1 - 0.85 * smoothstep(0.62, 0.9, node.radius);
    const driftX = Math.sin(cluster.speed[0] * t + cluster.phase[0]) * cluster.amplitude[0];
    const driftY = Math.sin(cluster.speed[1] * t + cluster.phase[1]) * cluster.amplitude[1];
    const driftZ = Math.sin(cluster.speed[2] * t + cluster.phase[2]) * cluster.amplitude[2];
    const interior = 1 - smoothstep(0.66, 0.92, node.radius);
    const factor = 1 + (spread - 1) * interior;
    let x = (node.x + driftX * pin) * factor;
    let y = (node.y + driftY * pin) * factor;
    const z = (node.z + driftZ * pin) * factor;
    if (speak > 0.001) {
      x *= 1 + 0.15 * speak * interior;
      y *= 1 - 0.1 * speak * interior;
      y += Math.sin(x * 6 - t * 3.4 + node.phase * 6.283) * (0.03 + 0.05 * m.speech) * speak * interior;
    }
    const perspective = 1 + 0.1 * z;
    screenX[index] = x * perspective;
    screenY[index] = y * perspective;
    screenZ[index] = z;

    let level = 0;
    for (const { tau, hops } of seeds) {
      const hop = hops[index]!;
      if (hop === latticeUnreachable) continue;
      level = Math.max(level, envelope(tau - hop * 0.24, 2.1, 12));
    }
    if (m.waveStrength > 0.001) {
      level = Math.max(level, m.waveStrength * Math.exp(-Math.pow((node.radius - m.wave * 1.05) / 0.17, 2)));
    }
    if (listen > 0.001) {
      const ripple = Math.pow(0.5 + 0.5 * Math.sin(node.radius * 10 + t * 3.2), 6);
      level = Math.max(level, listen * (0.18 + m.input * 0.9) * ripple);
    }
    if (heldSpeech > 0.001) {
      const ripple = Math.pow(0.5 + 0.5 * Math.sin(node.radius * 10 - t * 4.4), 6);
      level = Math.max(level, heldSpeech * 0.9 * ripple);
    }
    lit[index] = Math.min(1, level);
  });

  const scene: LatticeScene = {
    detail,
    edges: [],
    dots: [],
    signals: [],
    heart: { x: 0, y: 0, radius: 0.5, intensity: 0, heat: 0 },
    outerGain: Math.min(1.4, outerGain),
  };

  // Connections, bowed toward the centre.
  const curves = new Float64Array(model.edges.length * 6);
  const bowScale = 1 + 0.5 * think + 1.6 * speak - 0.5 * listen * (0.5 + m.input);
  model.edges.forEach((edge, index) => {
    const ax = screenX[edge.a]!, ay = screenY[edge.a]!, az = screenZ[edge.a]!;
    const bx = screenX[edge.b]!, by = screenY[edge.b]!, bz = screenZ[edge.b]!;
    const bow = edge.bow * bowScale;
    const mx = (ax + bx) / 2, my = (ay + by) / 2;
    const cx = mx * (1 - bow), cy = my * (1 - bow);
    curves.set([ax, ay, cx, cy, bx, by], index * 6);
    if (edge.rank > maximumRank) return;
    const na = model.nodes[edge.a]!;
    const nb = model.nodes[edge.b]!;
    const warmth = (na.warmth + nb.warmth) / 2;
    const gain = outerGain + (coreGain - outerGain) * warmth;
    const depth = 0.6 + 0.4 * ((az + bz) / 4 + 0.5);
    const light = Math.max(lit[edge.a]!, lit[edge.b]!) * 0.75;
    const length = Math.sqrt((ax - bx) * (ax - bx) + (ay - by) * (ay - by));
    const alpha = (0.19 + 0.26 * warmth) / (1 + length * (1.8 - 1.0 * warmth)) * gain * depth * alphasScale + light * 0.4;
    scene.edges.push({ ax, ay, cx, cy, bx, by, warmth, alpha: Math.min(1, alpha), light });
  });

  // Nodes.
  let heartX = 0;
  let heartY = 0;
  model.nodes.forEach((node, index) => {
    if (node.layer === coreLayer) {
      heartX += screenX[index]!;
      heartY += screenY[index]!;
    }
    if (node.rank > maximumRank) return;
    const z = screenZ[index]!;
    const depth = 0.62 + 0.38 * (z / 2 + 0.5);
    const twinkle = 0.78 + 0.22 * (0.5 + 0.5 * Math.sin(t * 0.9 + node.phase * 6.283));
    const gain = node.layer === coreLayer ? coreGain : node.layer === midLayer ? (outerGain + coreGain) / 2 : outerGain;
    const base = node.layer === shellLayer ? 0.8 : node.layer === midLayer ? 0.62 : 0.85;
    const alpha = Math.min(1, base * gain * depth * twinkle * Math.min(1.2, alphasScale) + lit[index]! * 0.55);
    const coreBeat = node.layer === coreLayer ? 1 + 0.18 * pulse : 1;
    scene.dots.push({
      x: screenX[index]!,
      y: screenY[index]!,
      radius: node.size * (1 + 0.35 * lit[index]!) * (1 + 0.1 * z) * dotsScale * coreBeat,
      warmth: node.warmth,
      alpha,
      halo: Math.min(1, lit[index]! * 0.8 + (node.rank === 0 ? 0.2 : 0)),
    });
  });
  const coreTotal = Math.max(1, model.coreNodes.length);
  heartX /= coreTotal;
  heartY /= coreTotal;

  // Signals, and the kick each one gives the heart when it arrives.
  let kick = 0;
  const active = 4 + 10 * awake + 6 * busy;
  model.routes.forEach((route, index) => {
    const fade = 1 - smoothstep(active - 1, active, index);
    if (fade <= 0.001) return;
    const hopCount = route.edges.length;
    const total = hopCount * route.hopDuration;
    const phase = wrap(flow + route.offset, route.period);
    if (phase > total) {
      kick += envelope(phase - total, 3.2, 18) * 0.3 * fade;
      return;
    }
    for (let tail = 0; tail < 5; tail += 1) {
      const age = phase - tail * 0.11;
      if (age < 0) break;
      const u = age / total;
      const scaled = Math.min(hopCount - 1e-9, u * hopCount);
      const hop = Math.trunc(scaled);
      const local = scaled - hop;
      const curve = route.edges[hop]! * 6;
      const s = route.forward[hop]! ? local : 1 - local;
      const inv = 1 - s;
      const x = inv * inv * curves[curve]! + 2 * inv * s * curves[curve + 2]! + s * s * curves[curve + 4]!;
      const y = inv * inv * curves[curve + 1]! + 2 * inv * s * curves[curve + 3]! + s * s * curves[curve + 5]!;
      const ends = smoothstep(0, 0.08, u) * smoothstep(0, 0.1, 1 - u);
      const strength = fade * ends * Math.pow(1 - tail / 5, 1.6);
      scene.signals.push({
        x, y,
        radius: 0.011 * (1 - tail * 0.13) * dotsScale,
        warmth: 0.1 + 0.9 * Math.pow(u, 1.6),
        alpha: Math.min(1, strength * 0.55 * alphasScale),
        halo: tail === 0 ? strength * 0.7 : 0,
      });
    }
  });

  const beat = 1 + 0.16 * pulse + Math.min(0.4, kick);
  scene.heart = {
    x: heartX,
    y: heartY,
    radius: 0.5 * (1 + 0.04 * pulse),
    intensity: Math.min(1.6, coreGain * beat * 0.5),
    heat: Math.min(1, 0.35 + 0.3 * pulse + kick + 0.25 * busy + 0.3 * heldSpeech),
  };
  return scene;
}
